contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0));

        uint256 contractBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        bool reverted;
        c.migrateTo(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            reverted
                ? address(c).balance == contractBalanceBefore
                : (address(c).balance == 0 && recipient.balance == recipientBalanceBefore + contractBalanceBefore)
        );
    }

    receive() external payable {}
}

